import gzip,glob
for f in sorted(glob.glob('studies/data/raw/*series_matrix*')):
    print('=====',f)
    for l in gzip.open(f,'rt',errors='ignore'):
        if l.startswith('!series_matrix_table_begin'): break
        if any(k in l for k in ['!Series_title','!Series_summary','!Series_overall_design','!Sample_title','!Sample_characteristics','!Sample_treatment_protocol','!Sample_source','!Sample_growth']):
            print(l[:1500].rstrip())

